use vstd::prelude::*;
use vstd::vec::*;

verus! {

// Specification function: defines what it means for a number to be even
spec fn is_even(n: u32) -> bool {
    n % 2 == 0
}

// Executable function that checks if a number is even
fn is_even_exec(n: u32) -> (result: bool)
    ensures
        result == is_even(n),
{
    n % 2 == 0
}

// Main function: checks if array contains at least one even number
fn is_product_even(arr: &Vec<u32>) -> (result: bool)
    ensures
        // If result is true, there exists an index with an even element
        result ==> (exists|k: int| 0 <= k < arr.len() && is_even(arr.index(k))),
        // If result is false, no element is even (or array is empty)
        !result ==> (forall|k: int| 0 <= k < arr.len() ==> !is_even(arr.index(k))),
{
    let mut i: usize = 0;
    let mut found_even = false;
    
    while i < arr.len()
        invariant
            0 <= i <= arr.len(),
            // found_even indicates we've found an even number in [0, i)
            found_even ==> (exists|k: int| 0 <= k < i && is_even(arr.index(k))),
            // If we haven't found an even number yet, then all elements in [0, i) are odd
            !found_even ==> (forall|k: int| 0 <= k < i ==> !is_even(arr.index(k))),
        decreases arr.len() - i,
    {
        let elem = arr[i];
        let is_elem_even = is_even_exec(elem);
        
        if is_elem_even {
            found_even = true;
        }
        
        i = i + 1;
    }
    
    // After loop, i == arr.len()
    // Postcondition follows from loop invariant
    found_even
}

} // verus!

